begin;
select no_plan();
select ok((select relrowsecurity from pg_class where oid='core.starter_item_working'::regclass),'Working overlay RLS');
select ok(not has_table_privilege('service_role','core.starter_item_working','SELECT'),'Even service has no table access');
select ok(not has_function_privilege('authenticated','api.execute_owner_starter_recovery_server(uuid,text,jsonb)','EXECUTE'),'Browser denied gateway');
select ok(not has_function_privilege('service_role','api.save_current_owner_starter_item_working(jsonb)','EXECUTE'),'Original save private');
set local role authenticated;
select throws_ok($$select api.execute_owner_starter_recovery_server('26100000-0000-4000-8000-000000000001','resolve_current_owner_starter_recovery','{}')$$,'42501',null,'Actual actor spoof denied');
reset role;
insert into auth.users(id,email) values('26100000-0000-4000-8000-000000000001','starter-one@example.test'),('26100000-0000-4000-8000-000000000002','starter-two@example.test');
create temporary table actors as select auth_user_id,owner_id from core.owner_auth_bindings where auth_user_id in('26100000-0000-4000-8000-000000000001','26100000-0000-4000-8000-000000000002');
update core.owners set onboarding_completed_at=now() where id in(select owner_id from actors);
update core.owner_onboarding_progress set current_step='preview_publish',primary_use_case='personal' where owner_id in(select owner_id from actors);
insert into core.owner_handle_namespaces(normalized_handle,owner_id,namespace_kind) select 'starter261-'||right(auth_user_id::text,6),owner_id,'current' from actors;
insert into core.identity_working(owner_id,display_name,revision) select owner_id,'Identity',1 from actors;
insert into core.identity_layout_working(owner_id,starter_key,revision) select owner_id,'clean',1 from actors;
insert into core.product_drafts(owner_id,source_url,title,revision) select owner_id,'https://shop.example.test/product',case when right(auth_user_id::text,1)='1' then 'First product' else 'Foreign product' end,2 from actors;
insert into core.resource_drafts(owner_id,resource_type,source_url,title,revision) select owner_id,'document','https://resource.example.test/document','Original resource',2 from actors;
insert into core.product_preparations(product_id,owner_id,destinations,revision) select id,owner_id,'[{"provider_key":"external:shop.example.test","destination_url":"https://shop.example.test/product"}]',4 from core.product_drafts where owner_id in(select owner_id from actors);
insert into core.spill_item_publications(item_id,owner_id,item_type,spill_reference,working_revision,snapshot,lifecycle_state,published_at)
 select item_id,owner_id,item_type,spill_reference,2,'{"original":true}','hidden',now() from core.spill_item_identity_registry where owner_id in(select owner_id from actors) and item_type='resource';
create temporary table preserved as select
 (select jsonb_agg(to_jsonb(d) order by d.id) from core.product_drafts d where owner_id in(select owner_id from actors)) products,
 (select jsonb_agg(to_jsonb(d) order by d.id) from core.resource_drafts d where owner_id in(select owner_id from actors)) resources,
 (select jsonb_agg(to_jsonb(d) order by d.product_id) from core.product_preparations d where owner_id in(select owner_id from actors)) preparation;
create function pg_temp.read_work(subject uuid) returns jsonb language sql as $$select api.execute_owner_starter_recovery_server(subject,'resolve_current_owner_starter_recovery','{}')$$;
create function pg_temp.save_work(subject uuid,ref bigint,source_base bigint,base bigint,title text,url text,meaning text) returns jsonb language sql as $$
 select api.execute_owner_starter_recovery_server(subject,'save_current_owner_starter_item_working',jsonb_build_object('input_working',jsonb_build_object('reference',ref,'base_source_revision',source_base,'base_working_revision',base,'working',jsonb_build_object('title',title,'source_url',url,'resource_type',meaning))))
$$;
set local request.jwt.claims='{"role":"service_role","sub":"26100000-0000-4000-8000-000000000002"}';
set local request.jwt.claim.sub='26100000-0000-4000-8000-000000000002';
set local role service_role;
select is(api.execute_owner_starter_recovery_server('26100000-0000-4000-8000-000000000001','save_current_owner_starter_item_working','{"input_working":"scalar"}')->>'status','invalid_working','Scalar body denied without exception');
select is(api.execute_owner_starter_recovery_server('26100000-0000-4000-8000-000000000001','save_current_owner_starter_item_working','{"input_working":{"owner_id":"26100000-0000-4000-8000-000000000002"}}')->>'status','invalid_working','Caller Owner target denied');
select is(api.execute_owner_starter_recovery_server('26100000-0000-4000-8000-000000000001','resolve_current_owner_starter_recovery','{"owner_id":"26100000-0000-4000-8000-000000000002"}')->>'status','unavailable','Read target denied');
select is(jsonb_array_length(pg_temp.read_work('26100000-0000-4000-8000-000000000001')->'items'),2,'Both capabilities shown even for Personal');
select is(pg_temp.read_work('26100000-0000-4000-8000-000000000001')#>>'{items,0,title}','First product','Own Product source');
select is(pg_temp.read_work('26100000-0000-4000-8000-000000000002')#>>'{items,0,title}','Foreign product','Same reference maps to second Owner own Product');
select is(pg_temp.save_work('26100000-0000-4000-8000-000000000001',1,2,null,'','javascript:raw()',null)->>'status','success','Invalid unfinished URL/title retained only in Working');
select is(pg_temp.read_work('26100000-0000-4000-8000-000000000001')#>>'{items,0,source_url}','javascript:raw()','Raw URL exact');
select is(pg_temp.read_work('26100000-0000-4000-8000-000000000001')#>>'{items,0,title}','','Empty title exact');
select is(pg_temp.read_work('26100000-0000-4000-8000-000000000002')#>>'{items,0,title}','Foreign product','Other Owner not overwritten');
select is(pg_temp.save_work('26100000-0000-4000-8000-000000000001',1,2,null,'Replay',null,null)->>'status','stale_write','Initial CAS replay denied');
select is(pg_temp.save_work('26100000-0000-4000-8000-000000000001',999,2,null,'Foreign target',null,null)->>'status','unavailable','Unknown reference uniform unavailable');
select is(pg_temp.save_work('26100000-0000-4000-8000-000000000001',1,2,1,'Wrong type',null,'document')->>'status','invalid_working','Product cannot become Resource');
select is(pg_temp.save_work('26100000-0000-4000-8000-000000000001',2,2,null,' <Raw> ',E' Raw\nURL ','media_kit')->>'status','success','Hidden Resource Working keeps explicit new meaning');
select is(pg_temp.read_work('26100000-0000-4000-8000-000000000001')#>>'{items,1,published_lifecycle}','hidden','Working save never restores hidden public state');
select is(current_setting('request.jwt.claim.sub'),'26100000-0000-4000-8000-000000000002','Legacy claim restored');
select is(current_setting('request.jwt.claims')::jsonb,'{"role":"service_role","sub":"26100000-0000-4000-8000-000000000002"}'::jsonb,'Service claims restored');
reset role;
select is((select jsonb_agg(to_jsonb(d) order by d.id) from core.product_drafts d where owner_id in(select owner_id from actors)),(select products from preserved),'Product source unchanged');
select is((select jsonb_agg(to_jsonb(d) order by d.id) from core.resource_drafts d where owner_id in(select owner_id from actors)),(select resources from preserved),'Resource source unchanged');
select is((select jsonb_agg(to_jsonb(d) order by d.product_id) from core.product_preparations d where owner_id in(select owner_id from actors)),(select preparation from preserved),'Product preparation untouched');
select ok(not exists(select 1 from core.spill_item_publications where owner_id in(select owner_id from actors) and snapshot<>'{"original":true}'::jsonb),'Published snapshot unchanged');
select is((select count(*)::integer from core.spill_item_identity_registry where owner_id in(select owner_id from actors)),4,'No new identity/reference allocation');
create function pg_temp.reject_starter_working() returns trigger language plpgsql as $$begin raise exception 'fixture starter failure';end;$$;
create trigger starter_fixture_failure before update on core.starter_item_working for each row execute function pg_temp.reject_starter_working();
set local role service_role;
select throws_ok($q$select pg_temp.save_work('26100000-0000-4000-8000-000000000001',1,2,1,'Exception',null,null)$q$,'P0001','fixture starter failure','Gateway never fabricates acknowledgment after exception');
select is(current_setting('request.jwt.claim.sub'),'26100000-0000-4000-8000-000000000002','Exception restores legacy actor');
select is(current_setting('request.jwt.claims')::jsonb,'{"role":"service_role","sub":"26100000-0000-4000-8000-000000000002"}'::jsonb,'Exception restores complete service claims');
reset role;
drop trigger starter_fixture_failure on core.starter_item_working;
update core.product_drafts set revision=3 where owner_id=(select owner_id from actors where auth_user_id='26100000-0000-4000-8000-000000000001');
set local role service_role;
select is(pg_temp.read_work('26100000-0000-4000-8000-000000000001')#>>'{items,0,source_changed}','true','Source drift explicit');
select is(pg_temp.read_work('26100000-0000-4000-8000-000000000001')#>>'{items,0,source_url}','javascript:raw()','Drift preserves raw Working');
select is(pg_temp.save_work('26100000-0000-4000-8000-000000000001',1,2,1,'Stale source',null,null)->>'status','stale_source','Old source CAS rejected');
select is(pg_temp.save_work('26100000-0000-4000-8000-000000000001',1,3,1,'Rebased',null,null)->>'working_revision','2','Explicit rebase against latest source accepted');
reset role;
update core.spill_item_publications set lifecycle_state='archived' where owner_id=(select owner_id from actors where auth_user_id='26100000-0000-4000-8000-000000000001');
set local role service_role;
select is(pg_temp.save_work('26100000-0000-4000-8000-000000000001',2,2,1,'Do not change archive',null,'document')->>'status','owner_not_eligible','Archived editing denied');
reset role;
update core.owners set account_state='restricted' where id=(select owner_id from actors where auth_user_id='26100000-0000-4000-8000-000000000001');
set local role service_role;
select is(pg_temp.read_work('26100000-0000-4000-8000-000000000001')->>'status','unavailable','Restricted read unavailable');
select is(pg_temp.save_work('26100000-0000-4000-8000-000000000001',1,3,2,'Restricted',null,null)->>'status','owner_not_eligible','Restricted save denied');
reset role;
select * from finish();
rollback;
